define({"topics":[{"title":"Adjusting the cradle release pin height","shortdesc":"<p class=\"shortdesc\">Adjust the cradle release pin to the correct height.<\/p>","href":"t_Cradle-Release-Pin-Height-Adjustment_15868448.html","attributes":{"data-id":"id_13106535"},"menu":{"hasChildren":false},"tocID":"id_13106535-d46e15471","topics":[]},{"title":"Adjusting the cradle\/LPCA release","shortdesc":"<p class=\"shortdesc\">Adjust the actuator on the LPCA so that it presses a button on the cradle to mechanically release the cradle from the patient table.<\/p>","href":"t_CradleLPCA-Release-Adjustment_15868433.html","attributes":{"data-id":"id_13106534"},"menu":{"hasChildren":false},"tocID":"id_13106534-d46e15576","topics":[]},{"title":"Adjusting the cradle\/table release block","shortdesc":"<p class=\"shortdesc\">Adjust the cradle release block position and the cradle release block retraction.<\/p>","href":"t_CradleTable-Release-Block-Adjustment_16502983.html","attributes":{"data-id":"id_15271090"},"menu":{"hasChildren":false},"tocID":"id_15271090-d46e15681","topics":[]},{"title":"Leveling the patient table","shortdesc":"<p class=\"shortdesc\">Adjust the patient table for floor levelness and do a check of the caster height. If adjustment is required, level the patient table.<\/p>","href":"t_Leveling-Patient-Table_16503070.html","attributes":{"data-id":"id_15271094"},"menu":{"hasChildren":false},"tocID":"id_15271094-d46e15786","topics":[]},{"title":"Adjusting the table top height","shortdesc":"<p class=\"shortdesc\">This procedure provides instructions on how to adjust the height of the table top.<\/p>","href":"t_Table-Top-Height-Adjustment_16502570.html","attributes":{"data-id":"id_15271086"},"menu":{"hasChildren":false},"tocID":"id_15271086-d46e15891","topics":[]}]});